class SamePlaceModule(dspy.Module):
    def __init__(self):
        super().__init__()
        self.predict = dspy.Predict(dspy.Signature(
            'input_name: str, input_address: str, match_name: str, match_address: str, distance: float -> is_same: bool',
            "Decide whether two business listings refer to the same physical place.\n\n"
            "You compare place A (input_name / input_address) with place B (match_name /\n"
            "match_address), plus the geographic distance between them."
        ))

    def forward(self, **inputs):
        import re

        input_name = str(inputs.get("input_name", "") or "")
        input_address = str(inputs.get("input_address", "") or "")
        match_name = str(inputs.get("match_name", "") or "")
        match_address = str(inputs.get("match_address", "") or "")
        try:
            distance = float(inputs.get("distance", 0.0) or 0.0)
        except (TypeError, ValueError):
            distance = 0.0

        # ---------- helpers ----------
        NAME_STOPWORDS = {
            "the", "a", "an", "and", "of", "&", "at",
            "restaurant", "restaurants", "cafe", "coffee", "shop", "store",
            "inc", "llc", "ltd", "co", "corp", "corporation", "company",
            "food", "foods", "kitchen", "grill", "bar", "bistro", "eatery",
            "house", "place", "market", "deli",
        }
        STREET_SUFFIXES = {
            "st": "st", "street": "st",
            "ave": "ave", "avenue": "ave",
            "blvd": "blvd", "boulevard": "blvd",
            "rd": "rd", "road": "rd",
            "dr": "dr", "drive": "dr",
            "ln": "ln", "lane": "ln",
            "ct": "ct", "court": "ct",
            "cir": "cir", "circle": "cir",
            "pl": "pl", "place": "pl",
            "pkwy": "pkwy", "parkway": "pkwy",
            "hwy": "hwy", "highway": "hwy",
            "way": "way",
            "ter": "ter", "terrace": "ter",
            "sq": "sq", "square": "sq",
            "trl": "trl", "trail": "trl",
        }
        DIRECTIONS = {
            "n": "n", "north": "n",
            "s": "s", "south": "s",
            "e": "e", "east": "e",
            "w": "w", "west": "w",
            "ne": "ne", "northeast": "ne",
            "nw": "nw", "northwest": "nw",
            "se": "se", "southeast": "se",
            "sw": "sw", "southwest": "sw",
        }

        def normalize_name(s):
            s = s.lower()
            s = re.sub(r"[^a-z0-9]+", " ", s)
            toks = [t for t in s.split() if t and t not in NAME_STOPWORDS]
            return toks

        def normalize_address(s):
            s = s.lower()
            s = re.sub(r"[^a-z0-9]+", " ", s)
            toks = s.split()
            out = []
            for t in toks:
                if t in STREET_SUFFIXES:
                    out.append(STREET_SUFFIXES[t])
                elif t in DIRECTIONS:
                    out.append(DIRECTIONS[t])
                else:
                    out.append(t)
            return out

        def extract_street_number(tokens):
            for t in tokens:
                if t.isdigit():
                    return t
            return None

        def token_jaccard(a, b):
            sa, sb = set(a), set(b)
            if not sa and not sb:
                return 1.0
            if not sa or not sb:
                return 0.0
            return len(sa & sb) / len(sa | sb)

        def levenshtein(a, b):
            if a == b:
                return 0
            if not a:
                return len(b)
            if not b:
                return len(a)
            if len(a) > len(b):
                a, b = b, a
            prev = list(range(len(a) + 1))
            for i, cb in enumerate(b, 1):
                cur = [i]
                for j, ca in enumerate(a, 1):
                    cost = 0 if ca == cb else 1
                    cur.append(min(cur[-1] + 1, prev[j] + 1, prev[j - 1] + cost))
                prev = cur
            return prev[-1]

        def str_sim(a, b):
            if not a and not b:
                return 1.0
            if not a or not b:
                return 0.0
            d = levenshtein(a, b)
            return 1.0 - d / max(len(a), len(b))

        # ---------- normalize ----------
        n_a_tokens = normalize_name(input_name)
        n_b_tokens = normalize_name(match_name)
        a_a_tokens = normalize_address(input_address)
        a_b_tokens = normalize_address(match_address)

        n_a_str = "".join(n_a_tokens)
        n_b_str = "".join(n_b_tokens)
        a_a_str = " ".join(a_a_tokens)
        a_b_str = " ".join(a_b_tokens)

        name_jacc = token_jaccard(n_a_tokens, n_b_tokens)
        name_edit_sim = str_sim(n_a_str, n_b_str)
        name_sim = max(name_jacc, name_edit_sim)

        addr_jacc = token_jaccard(a_a_tokens, a_b_tokens)
        addr_edit_sim = str_sim(a_a_str, a_b_str)
        addr_sim = max(addr_jacc, addr_edit_sim)

        num_a = extract_street_number(a_a_tokens)
        num_b = extract_street_number(a_b_tokens)
        same_number = (num_a is not None and num_b is not None and num_a == num_b)
        both_have_number = (num_a is not None and num_b is not None)
        diff_number = both_have_number and num_a != num_b

        # ---------- deterministic decisions ----------
        # Very far apart -> not same
        if distance > 500.0:
            return dspy.Prediction(is_same=False)

        # Different street numbers -> almost certainly not same
        if diff_number and addr_sim < 0.9:
            return dspy.Prediction(is_same=False)

        # Strong match: same street number, high name similarity, close distance
        if same_number and name_sim >= 0.6 and addr_sim >= 0.7 and distance <= 100.0:
            return dspy.Prediction(is_same=True)

        # Very high name+address similarity regardless
        if name_sim >= 0.75 and addr_sim >= 0.85 and distance <= 100.0:
            return dspy.Prediction(is_same=True)

        # Very low similarity on both -> not same
        if name_sim < 0.25 and addr_sim < 0.4:
            return dspy.Prediction(is_same=False)

        # Ambiguous: defer to LLM
        result = self.predict(
            input_name=input_name,
            input_address=input_address,
            match_name=match_name,
            match_address=match_address,
            distance=distance,
        )
        return dspy.Prediction(is_same=bool(result.is_same))
